Cooperative initialisers take keyword-only parameters and forward the rest, so unknown keywords reach `object.__init__` and fail. Each `quote` asks `super()` first and then appends a **class-qualified** step name, which keeps the audit trail correct whatever the instance's leftmost class is. `pricing_order` reads names from `vars(c)` along the reversed MRO, so the order in the class statement is testable.

**`pricing.py`**

```python
from dataclasses import dataclass, replace


@dataclass(frozen=True)
class Quote:
    amount: float
    steps: tuple[str, ...] = ()


class BaseFare:
    step_name = "base"

    def __init__(self, *, per_km: float = 10.0, **kwargs: object) -> None:
        self.per_km = per_km
        super().__init__(**kwargs)

    def quote(self, km: float) -> Quote:
        return Quote(self.per_km * km, (BaseFare.step_name,))


class SurgeMixin:
    step_name = "surge"

    def __init__(self, *, multiplier: float, **kwargs: object) -> None:
        self.multiplier = multiplier
        super().__init__(**kwargs)

    def quote(self, km: float) -> Quote:
        q = super().quote(km)
        return replace(q, amount=q.amount * self.multiplier, steps=q.steps + (SurgeMixin.step_name,))


class BookingFeeMixin:
    step_name = "booking_fee"

    def __init__(self, *, fee: float, **kwargs: object) -> None:
        self.fee = fee
        super().__init__(**kwargs)

    def quote(self, km: float) -> Quote:
        q = super().quote(km)
        return replace(q, amount=q.amount + self.fee, steps=q.steps + (BookingFeeMixin.step_name,))


class DiscountMixin:
    step_name = "discount"

    def __init__(self, *, percent: float, **kwargs: object) -> None:
        self.percent = percent
        super().__init__(**kwargs)

    def quote(self, km: float) -> Quote:
        q = super().quote(km)
        return replace(q, amount=q.amount * (1 - self.percent / 100), steps=q.steps + (DiscountMixin.step_name,))


def build_pricer(*mixins: type) -> type[BaseFare]:
    for m in mixins:
        if not isinstance(m, type) or issubclass(m, BaseFare) or not hasattr(m, "step_name"):
            raise TypeError(f"{m!r} is not a pricing mixin")
    name = "Pricer_" + "_".join(m.step_name for m in mixins)
    return type(name, (*mixins, BaseFare), {})  # duplicate mixins raise TypeError


def pricing_order(cls: type) -> list[str]:
    """Step names in the order they are applied (innermost first)."""
    return [c.step_name for c in reversed(cls.__mro__) if "step_name" in vars(c)]
```

**`test_pricing.py`**

```python
import pytest
from pricing import (BaseFare, BookingFeeMixin, DiscountMixin, SurgeMixin,
                     build_pricer, pricing_order)


def test_surge_applies_after_fee():
    q = build_pricer(SurgeMixin, BookingFeeMixin)(multiplier=2, fee=50).quote(10)
    assert q.amount == 300
    assert q.steps == ("base", "booking_fee", "surge")


def test_fee_applies_after_surge():
    p = build_pricer(BookingFeeMixin, SurgeMixin)(multiplier=2, fee=50)
    assert p.quote(10).amount == 250


def test_pricing_order_matches_mro():
    cls = build_pricer(DiscountMixin, SurgeMixin, BookingFeeMixin)
    assert pricing_order(cls) == ["base", "booking_fee", "surge", "discount"]


def test_unknown_keyword_is_rejected():
    with pytest.raises(TypeError):
        build_pricer(SurgeMixin)(multiplier=2, colour="red")


def test_missing_required_keyword_is_rejected():
    with pytest.raises(TypeError):
        build_pricer(SurgeMixin)()


def test_base_fare_not_allowed_as_mixin():
    with pytest.raises(TypeError):
        build_pricer(BaseFare)


def test_duplicate_mixin_rejected():
    with pytest.raises(TypeError):
        build_pricer(SurgeMixin, SurgeMixin)


def test_per_km_override():
    assert build_pricer()(per_km=12).quote(5).amount == 60
```

